/**
 * @name File path injection in INI config parser
 * @description User-controlled INI file content could lead to path traversal if used in file operations
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: reading from INI files (file read operations)
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: file path arguments to file system operations
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathInjectionFlow = TaintTracking::Global<PathInjectionConfig>;
import PathInjectionFlow::PathGraph

from PathInjectionFlow::PathNode source, PathInjectionFlow::PathNode sink
where PathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability: user input from $@ flows to file path.", source.getNode(), "INI file"

/**
 * @name Potential code injection in INI parsing
 * @description Check if parsed INI values could be used in eval/exec operations
 * @kind path-problem
 * @problem.severity warning
 * @id py/code-injection-ini
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module IniCodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: reading files that could contain malicious INI content
    source = any(FileSystemAccess fa).getAPathArgument()
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module IniCodeInjectionFlow = TaintTracking::Global<IniCodeInjectionConfig>;
import IniCodeInjectionFlow::PathGraph

from IniCodeInjectionFlow::PathNode source, IniCodeInjectionFlow::PathNode sink
where IniCodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection from INI file content to eval/exec $@.", source.getNode(), "INI file"
